.price-down { color: var(--negative); }

/* Sparkline placeholder */
.sparkline {
  display: inline-block;
  width: 60px;
  height: 20px;
  background: linear-gradient(90deg, transparent 0%, var(--accent-blue) 50%, transparent 100%);
