  margin-bottom: 1rem;
}
.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--accent-blue);
}
.broker-info { flex: 1; }
.broker-name { font-size: 1rem; font-weight: 600; margin-bottom: 0.25rem; }
.broker-tier { display: inline-block; margin-left: 0.5rem; }
.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.broker-rating-score {
  font-size: 1.125rem;
  font-weight: 700;
}
.broker-rating-label {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
}
.broker-rating-label.excellent { background: rgba(0,200,83,0.15); color: var(--positive); }
.broker-rating-label.great { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.broker-rating-label.good { background: rgba(255,179,0,0.15); color: var(--warning); }
.broker-stats {
  display: flex;
  gap: 1.5rem;
  padding: 0.75rem 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1rem;
}
.broker-stat { text-align: center; }
.broker-stat-value { font-size: 1rem; font-weight: 600; font-family: var(--font-mono); }
.broker-stat-label { font-size: 0.6875rem; color: var(--text-muted); }
.broker-promotion {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  border-radius: var(--radius-sm);
  padding: 0.625rem;
  font-size: 0.8125rem;
  color: var(--accent-blue);
  text-align: center;
}
.broker-actions { display: flex; gap: 0.5rem; margin-top: 1rem; }
.broker-actions .btn { flex: 1; }

.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  margin-bottom: 2rem;
}
.stats-banner h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}
.stats-banner p { color: var(--text-secondary); }

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.pagination-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
}
.pagination-btn:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.pagination-btn.active { background: var(--accent-blue); color: white; }
.pagination-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* Earnings Calendar */
.earnings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
}
.earnings-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 0.875rem;
}
.earnings-date {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-bottom: 0.375rem;
}
.earnings-company { font-weight: 600; font-size: 0.875rem; margin-bottom: 0.5rem; }
.earnings-values { display: flex; gap: 1rem; font-size: 0.75rem; }
.earnings-est { color: var(--text-muted); }
.earnings-act { color: var(--positive); font-weight: 500; }

/* Toggle switch */
.toggle-container {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.toggle {
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  position: relative;
  cursor: pointer;
  transition: background 200ms;
}
.toggle.active { background: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
}
.toggle.active::after { transform: translateX(16px); }

/* Responsive */
@media (max-width: 1200px) {
  .chart-layout { grid-template-columns: 220px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-layout { grid-template-columns: 1fr; }
  .watchlist-sidebar, .chart-panel { display: none; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 1.75rem; }
  .market-summary { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .ideas-grid { grid-template-columns: 1fr; }
  .broker-cards { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .market-summary { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeIn 300ms ease-out; }
