/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1a1a2e;
  --border-color: #2d2d44;
  --text-primary: #ffffff;
  --text-secondary: #a0a0b0;
  --text-muted: #6b6b7b;
  --accent-blue: #2962FF;
  --accent-teal: #00BCD4;
  --positive: #00C853;
  --negative: #F7525F;
  --warning: #FFB300;
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.4);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; }
table { border-collapse: collapse; width: 100%; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #404060; }

/* Layout */
.container { max-width: 1600px; margin: 0 auto; padding: 0 1rem; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 1rem;
  position: sticky;
  top: 0;
  z-index: 100;
}
.navbar-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 56px;
  max-width: 1600px;
  margin: 0 auto;
}
.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: -0.02em;
}
.logo span { color: var(--text-primary); }
.nav-links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 150ms;
}
.nav-links a:hover { color: var(--text-primary); }
.nav-actions { margin-left: auto; display: flex; gap: 0.75rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 150ms;
}
.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover { background: #1e5aff; }
.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover { background: #1e2a4a; }
.btn-ghost { color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.btn-sm { padding: 0.375rem 0.75rem; font-size: 0.8125rem; }

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--bg-tertiary);
  padding: 0.25rem;
  border-radius: var(--radius);
}
.tab {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
  cursor: pointer;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1rem;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.card-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  font-size: 0.8125rem;
}
.data-table th {
  text-align: left;
  padding: 0.625rem 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}
.data-table td {
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border-color);
}
.data-table tr:hover { background: rgba(255,255,255,0.02); }
.data-table .num { text-align: right; font-family: var(--font-mono); }

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.1875rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-positive { background: rgba(0,200,83,0.15); color: var(--positive); }
.badge-negative { background: rgba(247,82,95,0.15); color: var(--negative); }
.badge-neutral { background: rgba(255,255,255,0.1); color: var(--text-secondary); }
.badge-tier-platinum { background: linear-gradient(135deg, #1a1a2e, #2d2d44); border: 1px solid #4a4a6a; color: #e0e0f0; }
.badge-tier-gold { background: linear-gradient(135deg, #1a1a2e, #2d2a1a); border: 1px solid #6a5a2a; color: #f0d080; }

/* Price display */
.price { font-family: var(--font-mono); font-weight: 500; }
.price-up { color: var(--positive); }
.price-down { color: var(--negative); }

/* Sparkline placeholder */
.sparkline {
  display: inline-block;
  width: 60px;
  height: 20px;
  background: linear-gradient(90deg, transparent 0%, var(--accent-blue) 50%, transparent 100%);
  opacity: 0.3;
  border-radius: 2px;
  vertical-align: middle;
}

/* Hero */
.hero {
  padding: 4rem 0;
  text-align: center;
  background: radial-gradient(ellipse at top, var(--bg-tertiary) 0%, var(--bg-primary) 70%);
}
.hero h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}
.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 2rem;
}
.hero-actions { display: flex; gap: 1rem; justify-content: center; }

/* Market Summary Bar */
.market-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  padding: 1rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}
.market-item {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem;
  background: var(--bg-card);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}
.market-item-label {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.market-item-value {
  font-family: var(--font-mono);
  font-size: 0.9375rem;
  font-weight: 600;
}
.market-item-change { font-size: 0.8125rem; font-weight: 500; }

/* Section */
.section { padding: 2rem 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.section-title {
  font-size: 1.125rem;
  font-weight: 600;
}

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

/* Stock list compact */
.stock-list { list-style: none; }
.stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0;
  border-bottom: 1px solid var(--border-color);
}
.stock-item:last-child { border-bottom: none; }
.stock-info { display: flex; flex-direction: column; gap: 0.125rem; }
.stock-ticker { font-weight: 600; font-size: 0.875rem; }
.stock-name { font-size: 0.75rem; color: var(--text-muted); }
.stock-price { text-align: right; }
.stock-price-value { font-family: var(--font-mono); font-weight: 500; }
.stock-price-change { font-size: 0.75rem; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0 1.5rem;
  margin-top: 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}
.footer-col-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-links a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color 150ms;
}
.footer-links a:hover { color: var(--text-primary); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Page specific: Chart */
.chart-layout {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}
.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0.75rem;
}
.watchlist-category {
  margin-bottom: 0.5rem;
}
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background 150ms;
}
.watchlist-header:hover { background: rgba(255,255,255,0.05); }
.watchlist-header h4 {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}
.watchlist-header .chevron { transition: transform 200ms; }
.watchlist-header.expanded .chevron { transform: rotate(180deg); }
.watchlist-items { display: none; padding: 0.25rem 0; }
.watchlist-items.show { display: block; }
.watchlist-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 150ms;
}
.watchlist-item:hover { background: rgba(255,255,255,0.05); }
.watchlist-item.active { background: rgba(41,98,255,0.2); }
.watchlist-symbol { font-weight: 600; font-size: 0.8125rem; }
.watchlist-price { font-family: var(--font-mono); font-size: 0.75rem; }
.watchlist-change { font-size: 0.6875rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}
.chart-actions { display: flex; gap: 0.5rem; }
.timeframe-selector { display: flex; gap: 0.125rem; }
.timeframe-btn {
  padding: 0.375rem 0.625rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all 150ms;
}
.timeframe-btn:hover { color: var(--text-primary); }
.timeframe-btn.active { background: var(--accent-blue); color: white; }
.chart-container {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.candlestick-chart {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 1rem;
  gap: 2px;
}
.candle {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 8px;
}
.candle-body {
  width: 100%;
  border-radius: 1px;
}
.candle-wick {
  width: 1px;
}
.candle.up .candle-body { background: var(--positive); }
.candle.up .candle-wick { background: var(--positive); }
.candle.down .candle-body { background: var(--negative); }
.candle.down .candle-wick { background: var(--negative); }

.chart-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 1rem;
}
.panel-section {
  margin-bottom: 1.5rem;
}
.panel-section-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}
.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}
.detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  padding: 0.5rem;
  background: var(--bg-card);
  border-radius: var(--radius-sm);
}
.detail-label { font-size: 0.6875rem; color: var(--text-muted); }
.detail-value { font-size: 0.875rem; font-weight: 600; font-family: var(--font-mono); }

/* Page: Ideas */
.ideas-layout { max-width: 1200px; margin: 0 auto; padding: 1.5rem 1rem; }
.ideas-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}
.filter-bar {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.filter-bar .tabs { flex: 1; max-width: 400px; }
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 1rem;
}
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.idea-card:hover { border-color: var(--accent-blue); }
.idea-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.875rem;
}
.idea-meta { flex: 1; }
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-badge {
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  background: rgba(41,98,255,0.2);
  color: var(--accent-blue);
}
.idea-chart-preview {
  height: 120px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.idea-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  line-height: 1.3;
}
.idea-description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.5;
}
.idea-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-color);
}
.idea-stats { display: flex; gap: 1rem; }
.idea-stat { font-size: 0.75rem; color: var(--text-muted); }
.idea-ticker {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent-blue);
}

/* Page: Markets */
.markets-layout { padding: 1rem; max-width: 1600px; margin: 0 auto; }
.asset-tabs {
  display: flex;
  gap: 0.125rem;
  padding: 0.25rem;
  background: var(--bg-secondary);
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  overflow-x: auto;
}
.asset-tab {
  padding: 0.625rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all 150ms;
  cursor: pointer;
}
.asset-tab:hover { color: var(--text-primary); }
.asset-tab.active { background: var(--accent-blue); color: white; }
.markets-section { margin-bottom: 2rem; }
.markets-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.markets-section-title {
  font-size: 1rem;
  font-weight: 600;
}
.chart-type-toggle {
  display: flex;
  gap: 0.125rem;
  background: var(--bg-tertiary);
  padding: 0.125rem;
  border-radius: var(--radius-sm);
}
.chart-type-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.6875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 2px;
  transition: all 150ms;
}
.chart-type-btn:hover { color: var(--text-primary); }
.chart-type-btn.active { background: var(--bg-card); color: var(--text-primary); }
.mini-chart {
  width: 80px;
  height: 30px;
  display: inline-block;
  vertical-align: middle;
}

/* Page: Brokers */
.brokers-layout { max-width: 1200px; margin: 0 auto; padding: 2rem 1rem; }
.brokers-hero {
  text-align: center;
  padding: 2rem 0 3rem;
}
.brokers-hero h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}
.brokers-hero p {
  color: var(--text-secondary);
  font-size: 1.125rem;
}
.broker-filters {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.broker-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
}
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.broker-card:hover { border-color: var(--accent-blue); }
.broker-header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
}
.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--accent-blue);
}
.broker-info { flex: 1; }
.broker-name { font-size: 1rem; font-weight: 600; margin-bottom: 0.25rem; }
.broker-tier { display: inline-block; margin-left: 0.5rem; }
.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.broker-rating-score {
  font-size: 1.125rem;
  font-weight: 700;
}
.broker-rating-label {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
}
.broker-rating-label.excellent { background: rgba(0,200,83,0.15); color: var(--positive); }
.broker-rating-label.great { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.broker-rating-label.good { background: rgba(255,179,0,0.15); color: var(--warning); }
.broker-stats {
  display: flex;
  gap: 1.5rem;
  padding: 0.75rem 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1rem;
}
.broker-stat { text-align: center; }
.broker-stat-value { font-size: 1rem; font-weight: 600; font-family: var(--font-mono); }
.broker-stat-label { font-size: 0.6875rem; color: var(--text-muted); }
.broker-promotion {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  border-radius: var(--radius-sm);
  padding: 0.625rem;
  font-size: 0.8125rem;
  color: var(--accent-blue);
  text-align: center;
}
.broker-actions { display: flex; gap: 0.5rem; margin-top: 1rem; }
.broker-actions .btn { flex: 1; }

.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  margin-bottom: 2rem;
}
.stats-banner h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}
.stats-banner p { color: var(--text-secondary); }

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.pagination-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
}
.pagination-btn:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.pagination-btn.active { background: var(--accent-blue); color: white; }
.pagination-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* Earnings Calendar */
.earnings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
}
.earnings-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 0.875rem;
}
.earnings-date {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-bottom: 0.375rem;
}
.earnings-company { font-weight: 600; font-size: 0.875rem; margin-bottom: 0.5rem; }
.earnings-values { display: flex; gap: 1rem; font-size: 0.75rem; }
.earnings-est { color: var(--text-muted); }
.earnings-act { color: var(--positive); font-weight: 500; }

/* Toggle switch */
.toggle-container {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.toggle {
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  position: relative;
  cursor: pointer;
  transition: background 200ms;
}
.toggle.active { background: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
}
.toggle.active::after { transform: translateX(16px); }

/* Responsive */
@media (max-width: 1200px) {
  .chart-layout { grid-template-columns: 220px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-layout { grid-template-columns: 1fr; }
  .watchlist-sidebar, .chart-panel { display: none; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 1.75rem; }
  .market-summary { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .ideas-grid { grid-template-columns: 1fr; }
  .broker-cards { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .market-summary { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeIn 300ms ease-out; }

/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1a1a2e;
  --border-color: #2d2d44;
  --text-primary: #ffffff;
  --text-secondary: #a0a0b0;
  --text-muted: #6b6b7b;
  --accent-blue: #2962FF;
  --accent-teal: #00BCD4;
  --positive: #00C853;
  --negative: #F7525F;
  --warning: #FFB300;
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.4);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; }
table { border-collapse: collapse; width: 100%; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #404060; }

/* Layout */
.container { max-width: 1600px; margin: 0 auto; padding: 0 1rem; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 1rem;
  position: sticky;
  top: 0;
  z-index: 100;
}
.navbar-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 56px;
  max-width: 1600px;
  margin: 0 auto;
}
.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: -0.02em;
}
.logo span { color: var(--text-primary); }
.nav-links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 150ms;
}
.nav-links a:hover { color: var(--text-primary); }
.nav-actions { margin-left: auto; display: flex; gap: 0.75rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 150ms;
}
.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover { background: #1e5aff; }
.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover { background: #1e2a4a; }
.btn-ghost { color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.btn-sm { padding: 0.375rem 0.75rem; font-size: 0.8125rem; }

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--bg-tertiary);
  padding: 0.25rem;
  border-radius: var(--radius);
}
.tab {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
  cursor: pointer;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1rem;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.card-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  font-size: 0.8125rem;
}
.data-table th {
  text-align: left;
  padding: 0.625rem 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}
.data-table td {
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border-color);
}
.data-table tr:hover { background: rgba(255,255,255,0.02); }
.data-table .num { text-align: right; font-family: var(--font-mono); }

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.1875rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-positive { background: rgba(0,200,83,0.15); color: var(--positive); }
.badge-negative { background: rgba(247,82,95,0.15); color: var(--negative); }
.badge-neutral { background: rgba(255,255,255,0.1); color: var(--text-secondary); }
.badge-tier-platinum { background: linear-gradient(135deg, #1a1a2e, #2d2d44); border: 1px solid #4a4a6a; color: #e0e0f0; }
.badge-tier-gold { background: linear-gradient(135deg, #1a1a2e, #2d2a1a); border: 1px solid #6a5a2a; color: #f0d080; }

/* Price display */
.price { font-family: var(--font-mono); font-weight: 500; }
.price-up { color: var(--positive); }
.price-down { color: var(--negative); }

/* Sparkline placeholder */
.sparkline {
  display: inline-block;
  width: 60px;
  height: 20px;
  background: linear-gradient(90deg, transparent 0%, var(--accent-blue) 50%, transparent 100%);
  opacity: 0.3;
  border-radius: 2px;
  vertical-align: middle;
}

/* Hero */
.hero {
  padding: 4rem 0;
  text-align: center;
  background: radial-gradient(ellipse at top, var(--bg-tertiary) 0%, var(--bg-primary) 70%);
}
.hero h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}
.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 2rem;
}
.hero-actions { display: flex; gap: 1rem; justify-content: center; }

/* Market Summary Bar */
.market-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  padding: 1rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}
.market-item {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem;
  background: var(--bg-card);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}
.market-item-label {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.market-item-value {
  font-family: var(--font-mono);
  font-size: 0.9375rem;
  font-weight: 600;
}
.market-item-change { font-size: 0.8125rem; font-weight: 500; }

/* Section */
.section { padding: 2rem 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.section-title {
  font-size: 1.125rem;
  font-weight: 600;
}

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

/* Stock list compact */
.stock-list { list-style: none; }
.stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0;
  border-bottom: 1px solid var(--border-color);
}
.stock-item:last-child { border-bottom: none; }
.stock-info { display: flex; flex-direction: column; gap: 0.125rem; }
.stock-ticker { font-weight: 600; font-size: 0.875rem; }
.stock-name { font-size: 0.75rem; color: var(--text-muted); }
.stock-price { text-align: right; }
.stock-price-value { font-family: var(--font-mono); font-weight: 500; }
.stock-price-change { font-size: 0.75rem; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0 1.5rem;
  margin-top: 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}
.footer-col-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-links a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color 150ms;
}
.footer-links a:hover { color: var(--text-primary); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Page specific: Chart */
.chart-layout {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}
.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0.75rem;
}
.watchlist-category {
  margin-bottom: 0.5rem;
}
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background 150ms;
}
.watchlist-header:hover { background: rgba(255,255,255,0.05); }
.watchlist-header h4 {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}
.watchlist-header .chevron { transition: transform 200ms; }
.watchlist-header.expanded .chevron { transform: rotate(180deg); }
.watchlist-items { display: none; padding: 0.25rem 0; }
.watchlist-items.show { display: block; }
.watchlist-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 150ms;
}
.watchlist-item:hover { background: rgba(255,255,255,0.05); }
.watchlist-item.active { background: rgba(41,98,255,0.2); }
.watchlist-symbol { font-weight: 600; font-size: 0.8125rem; }
.watchlist-price { font-family: var(--font-mono); font-size: 0.75rem; }
.watchlist-change { font-size: 0.6875rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}
.chart-actions { display: flex; gap: 0.5rem; }
.timeframe-selector { display: flex; gap: 0.125rem; }
.timeframe-btn {
  padding: 0.375rem 0.625rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all 150ms;
}
.timeframe-btn:hover { color: var(--text-primary); }
.timeframe-btn.active { background: var(--accent-blue); color: white; }
.chart-container {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.candlestick-chart {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 1rem;
  gap: 2px;
}
.candle {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 8px;
}
.candle-body {
  width: 100%;
  border-radius: 1px;
}
.candle-wick {
  width: 1px;
}
.candle.up .candle-body { background: var(--positive); }
.candle.up .candle-wick { background: var(--positive); }
.candle.down .candle-body { background: var(--negative); }
.candle.down .candle-wick { background: var(--negative); }

.chart-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 1rem;
}
.panel-section {
  margin-bottom: 1.5rem;
}
.panel-section-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}
.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}
.detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  padding: 0.5rem;
  background: var(--bg-card);
  border-radius: var(--radius-sm);
}
.detail-label { font-size: 0.6875rem; color: var(--text-muted); }
.detail-value { font-size: 0.875rem; font-weight: 600; font-family: var(--font-mono); }

/* Page: Ideas */
.ideas-layout { max-width: 1200px; margin: 0 auto; padding: 1.5rem 1rem; }
.ideas-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}
.filter-bar {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.filter-bar .tabs { flex: 1; max-width: 400px; }
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 1rem;
}
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.idea-card:hover { border-color: var(--accent-blue); }
.idea-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.875rem;
}
.idea-meta { flex: 1; }
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-badge {
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  background: rgba(41,98,255,0.2);
  color: var(--accent-blue);
}
.idea-chart-preview {
  height: 120px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.idea-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  line-height: 1.3;
}
.idea-description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.5;
}
.idea-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-color);
}
.idea-stats { display: flex; gap: 1rem; }
.idea-stat { font-size: 0.75rem; color: var(--text-muted); }
.idea-ticker {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent-blue);
}

/* Page: Markets */
.markets-layout { padding: 1rem; max-width: 1600px; margin: 0 auto; }
.asset-tabs {
  display: flex;
  gap: 0.125rem;
  padding: 0.25rem;
  background: var(--bg-secondary);
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  overflow-x: auto;
}
.asset-tab {
  padding: 0.625rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all 150ms;
  cursor: pointer;
}
.asset-tab:hover { color: var(--text-primary); }
.asset-tab.active { background: var(--accent-blue); color: white; }
.markets-section { margin-bottom: 2rem; }
.markets-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.markets-section-title {
  font-size: 1rem;
  font-weight: 600;
}
.chart-type-toggle {
  display: flex;
  gap: 0.125rem;
  background: var(--bg-tertiary);
  padding: 0.125rem;
  border-radius: var(--radius-sm);
}
.chart-type-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.6875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 2px;
  transition: all 150ms;
}
.chart-type-btn:hover { color: var(--text-primary); }
.chart-type-btn.active { background: var(--bg-card); color: var(--text-primary); }
.mini-chart {
  width: 80px;
  height: 30px;
  display: inline-block;
  vertical-align: middle;
}

/* Page: Brokers */
.brokers-layout { max-width: 1200px; margin: 0 auto; padding: 2rem 1rem; }
.brokers-hero {
  text-align: center;
  padding: 2rem 0 3rem;
}
.brokers-hero h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}
.brokers-hero p {
  color: var(--text-secondary);
  font-size: 1.125rem;
}
.broker-filters {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.broker-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
}
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.broker-card:hover { border-color: var(--accent-blue); }
.broker-header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
}
.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--accent-blue);
}
.broker-info { flex: 1; }
.broker-name { font-size: 1rem; font-weight: 600; margin-bottom: 0.25rem; }
.broker-tier { display: inline-block; margin-left: 0.5rem; }
.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.broker-rating-score {
  font-size: 1.125rem;
  font-weight: 700;
}
.broker-rating-label {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
}
.broker-rating-label.excellent { background: rgba(0,200,83,0.15); color: var(--positive); }
.broker-rating-label.great { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.broker-rating-label.good { background: rgba(255,179,0,0.15); color: var(--warning); }
.broker-stats {
  display: flex;
  gap: 1.5rem;
  padding: 0.75rem 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1rem;
}
.broker-stat { text-align: center; }
.broker-stat-value { font-size: 1rem; font-weight: 600; font-family: var(--font-mono); }
.broker-stat-label { font-size: 0.6875rem; color: var(--text-muted); }
.broker-promotion {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  border-radius: var(--radius-sm);
  padding: 0.625rem;
  font-size: 0.8125rem;
  color: var(--accent-blue);
  text-align: center;
}
.broker-actions { display: flex; gap: 0.5rem; margin-top: 1rem; }
.broker-actions .btn { flex: 1; }

.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  margin-bottom: 2rem;
}
.stats-banner h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}
.stats-banner p { color: var(--text-secondary); }

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.pagination-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
}
.pagination-btn:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.pagination-btn.active { background: var(--accent-blue); color: white; }
.pagination-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* Earnings Calendar */
.earnings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
}
.earnings-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 0.875rem;
}
.earnings-date {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-bottom: 0.375rem;
}
.earnings-company { font-weight: 600; font-size: 0.875rem; margin-bottom: 0.5rem; }
.earnings-values { display: flex; gap: 1rem; font-size: 0.75rem; }
.earnings-est { color: var(--text-muted); }
.earnings-act { color: var(--positive); font-weight: 500; }

/* Toggle switch */
.toggle-container {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.toggle {
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  position: relative;
  cursor: pointer;
  transition: background 200ms;
}
.toggle.active { background: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
}
.toggle.active::after { transform: translateX(16px); }

/* Responsive */
@media (max-width: 1200px) {
  .chart-layout { grid-template-columns: 220px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-layout { grid-template-columns: 1fr; }
  .watchlist-sidebar, .chart-panel { display: none; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 1.75rem; }
  .market-summary { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .ideas-grid { grid-template-columns: 1fr; }
  .broker-cards { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .market-summary { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeIn 300ms ease-out; }

raw_arguments.content:
/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-tertiary: #16213e;
  --bg-card: #1a1a2e;
  --border-color: #2d2d44;
  --text-primary: #ffffff;
  --text-secondary: #a0a0b0;
  --text-muted: #6b6b7b;
  --accent-blue: #2962FF;
  --accent-teal: #00BCD4;
  --positive: #00C853;
  --negative: #F7525F;
  --warning: #FFB300;
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.4);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, select { font-family: inherit; }
table { border-collapse: collapse; width: 100%; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-secondary); }
::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #404060; }

/* Layout */
.container { max-width: 1600px; margin: 0 auto; padding: 0 1rem; }

/* Navigation */
.navbar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 0 1rem;
  position: sticky;
  top: 0;
  z-index: 100;
}
.navbar-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 56px;
  max-width: 1600px;
  margin: 0 auto;
}
.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: -0.02em;
}
.logo span { color: var(--text-primary); }
.nav-links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
}
.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 150ms;
}
.nav-links a:hover { color: var(--text-primary); }
.nav-actions { margin-left: auto; display: flex; gap: 0.75rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 150ms;
}
.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover { background: #1e5aff; }
.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover { background: #1e2a4a; }
.btn-ghost { color: var(--text-secondary); }
.btn-ghost:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.btn-sm { padding: 0.375rem 0.75rem; font-size: 0.8125rem; }

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--bg-tertiary);
  padding: 0.25rem;
  border-radius: var(--radius);
}
.tab {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
  cursor: pointer;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1rem;
}
.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.card-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Tables */
.data-table {
  width: 100%;
  font-size: 0.8125rem;
}
.data-table th {
  text-align: left;
  padding: 0.625rem 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
}
.data-table td {
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border-color);
}
.data-table tr:hover { background: rgba(255,255,255,0.02); }
.data-table .num { text-align: right; font-family: var(--font-mono); }

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.1875rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-positive { background: rgba(0,200,83,0.15); color: var(--positive); }
.badge-negative { background: rgba(247,82,95,0.15); color: var(--negative); }
.badge-neutral { background: rgba(255,255,255,0.1); color: var(--text-secondary); }
.badge-tier-platinum { background: linear-gradient(135deg, #1a1a2e, #2d2d44); border: 1px solid #4a4a6a; color: #e0e0f0; }
.badge-tier-gold { background: linear-gradient(135deg, #1a1a2e, #2d2a1a); border: 1px solid #6a5a2a; color: #f0d080; }

/* Price display */
.price { font-family: var(--font-mono); font-weight: 500; }
.price-up { color: var(--positive); }
.price-down { color: var(--negative); }

/* Sparkline placeholder */
.sparkline {
  display: inline-block;
  width: 60px;
  height: 20px;
  background: linear-gradient(90deg, transparent 0%, var(--accent-blue) 50%, transparent 100%);
  opacity: 0.3;
  border-radius: 2px;
  vertical-align: middle;
}

/* Hero */
.hero {
  padding: 4rem 0;
  text-align: center;
  background: radial-gradient(ellipse at top, var(--bg-tertiary) 0%, var(--bg-primary) 70%);
}
.hero h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}
.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 2rem;
}
.hero-actions { display: flex; gap: 1rem; justify-content: center; }

/* Market Summary Bar */
.market-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  padding: 1rem;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}
.market-item {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.75rem;
  background: var(--bg-card);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}
.market-item-label {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.market-item-value {
  font-family: var(--font-mono);
  font-size: 0.9375rem;
  font-weight: 600;
}
.market-item-change { font-size: 0.8125rem; font-weight: 500; }

/* Section */
.section { padding: 2rem 0; }
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.section-title {
  font-size: 1.125rem;
  font-weight: 600;
}

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

/* Stock list compact */
.stock-list { list-style: none; }
.stock-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.625rem 0;
  border-bottom: 1px solid var(--border-color);
}
.stock-item:last-child { border-bottom: none; }
.stock-info { display: flex; flex-direction: column; gap: 0.125rem; }
.stock-ticker { font-weight: 600; font-size: 0.875rem; }
.stock-name { font-size: 0.75rem; color: var(--text-muted); }
.stock-price { text-align: right; }
.stock-price-value { font-family: var(--font-mono); font-weight: 500; }
.stock-price-change { font-size: 0.75rem; }

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0 1.5rem;
  margin-top: 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}
.footer-col-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-links a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color 150ms;
}
.footer-links a:hover { color: var(--text-primary); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Page specific: Chart */
.chart-layout {
  display: grid;
  grid-template-columns: 260px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}
.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 0.75rem;
}
.watchlist-category {
  margin-bottom: 0.5rem;
}
.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: background 150ms;
}
.watchlist-header:hover { background: rgba(255,255,255,0.05); }
.watchlist-header h4 {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}
.watchlist-header .chevron { transition: transform 200ms; }
.watchlist-header.expanded .chevron { transform: rotate(180deg); }
.watchlist-items { display: none; padding: 0.25rem 0; }
.watchlist-items.show { display: block; }
.watchlist-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 150ms;
}
.watchlist-item:hover { background: rgba(255,255,255,0.05); }
.watchlist-item.active { background: rgba(41,98,255,0.2); }
.watchlist-symbol { font-weight: 600; font-size: 0.8125rem; }
.watchlist-price { font-family: var(--font-mono); font-size: 0.75rem; }
.watchlist-change { font-size: 0.6875rem; }

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}
.chart-actions { display: flex; gap: 0.5rem; }
.timeframe-selector { display: flex; gap: 0.125rem; }
.timeframe-btn {
  padding: 0.375rem 0.625rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all 150ms;
}
.timeframe-btn:hover { color: var(--text-primary); }
.timeframe-btn.active { background: var(--accent-blue); color: white; }
.chart-container {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  overflow: hidden;
}
.candlestick-chart {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 1rem;
  gap: 2px;
}
.candle {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 8px;
}
.candle-body {
  width: 100%;
  border-radius: 1px;
}
.candle-wick {
  width: 1px;
}
.candle.up .candle-body { background: var(--positive); }
.candle.up .candle-wick { background: var(--positive); }
.candle.down .candle-body { background: var(--negative); }
.candle.down .candle-wick { background: var(--negative); }

.chart-panel {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border-color);
  overflow-y: auto;
  padding: 1rem;
}
.panel-section {
  margin-bottom: 1.5rem;
}
.panel-section-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}
.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}
.detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  padding: 0.5rem;
  background: var(--bg-card);
  border-radius: var(--radius-sm);
}
.detail-label { font-size: 0.6875rem; color: var(--text-muted); }
.detail-value { font-size: 0.875rem; font-weight: 600; font-family: var(--font-mono); }

/* Page: Ideas */
.ideas-layout { max-width: 1200px; margin: 0 auto; padding: 1.5rem 1rem; }
.ideas-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}
.filter-bar {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
}
.filter-bar .tabs { flex: 1; max-width: 400px; }
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 1rem;
}
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.idea-card:hover { border-color: var(--accent-blue); }
.idea-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.875rem;
}
.idea-meta { flex: 1; }
.idea-author { font-weight: 600; font-size: 0.875rem; }
.idea-time { font-size: 0.75rem; color: var(--text-muted); }
.idea-badge {
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  background: rgba(41,98,255,0.2);
  color: var(--accent-blue);
}
.idea-chart-preview {
  height: 120px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.idea-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  line-height: 1.3;
}
.idea-description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  line-height: 1.5;
}
.idea-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-color);
}
.idea-stats { display: flex; gap: 1rem; }
.idea-stat { font-size: 0.75rem; color: var(--text-muted); }
.idea-ticker {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--accent-blue);
}

/* Page: Markets */
.markets-layout { padding: 1rem; max-width: 1600px; margin: 0 auto; }
.asset-tabs {
  display: flex;
  gap: 0.125rem;
  padding: 0.25rem;
  background: var(--bg-secondary);
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  overflow-x: auto;
}
.asset-tab {
  padding: 0.625rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all 150ms;
  cursor: pointer;
}
.asset-tab:hover { color: var(--text-primary); }
.asset-tab.active { background: var(--accent-blue); color: white; }
.markets-section { margin-bottom: 2rem; }
.markets-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.markets-section-title {
  font-size: 1rem;
  font-weight: 600;
}
.chart-type-toggle {
  display: flex;
  gap: 0.125rem;
  background: var(--bg-tertiary);
  padding: 0.125rem;
  border-radius: var(--radius-sm);
}
.chart-type-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.6875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 2px;
  transition: all 150ms;
}
.chart-type-btn:hover { color: var(--text-primary); }
.chart-type-btn.active { background: var(--bg-card); color: var(--text-primary); }
.mini-chart {
  width: 80px;
  height: 30px;
  display: inline-block;
  vertical-align: middle;
}

/* Page: Brokers */
.brokers-layout { max-width: 1200px; margin: 0 auto; padding: 2rem 1rem; }
.brokers-hero {
  text-align: center;
  padding: 2rem 0 3rem;
}
.brokers-hero h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}
.brokers-hero p {
  color: var(--text-secondary);
  font-size: 1.125rem;
}
.broker-filters {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.broker-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
}
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: border-color 200ms;
}
.broker-card:hover { border-color: var(--accent-blue); }
.broker-header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
}
.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--accent-blue);
}
.broker-info { flex: 1; }
.broker-name { font-size: 1rem; font-weight: 600; margin-bottom: 0.25rem; }
.broker-tier { display: inline-block; margin-left: 0.5rem; }
.broker-rating {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.broker-rating-score {
  font-size: 1.125rem;
  font-weight: 700;
}
.broker-rating-label {
  font-size: 0.75rem;
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
}
.broker-rating-label.excellent { background: rgba(0,200,83,0.15); color: var(--positive); }
.broker-rating-label.great { background: rgba(41,98,255,0.15); color: var(--accent-blue); }
.broker-rating-label.good { background: rgba(255,179,0,0.15); color: var(--warning); }
.broker-stats {
  display: flex;
  gap: 1.5rem;
  padding: 0.75rem 0;
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 1rem;
}
.broker-stat { text-align: center; }
.broker-stat-value { font-size: 1rem; font-weight: 600; font-family: var(--font-mono); }
.broker-stat-label { font-size: 0.6875rem; color: var(--text-muted); }
.broker-promotion {
  background: rgba(41,98,255,0.1);
  border: 1px solid rgba(41,98,255,0.3);
  border-radius: var(--radius-sm);
  padding: 0.625rem;
  font-size: 0.8125rem;
  color: var(--accent-blue);
  text-align: center;
}
.broker-actions { display: flex; gap: 0.5rem; margin-top: 1rem; }
.broker-actions .btn { flex: 1; }

.stats-banner {
  background: linear-gradient(135deg, var(--bg-tertiary), var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  margin-bottom: 2rem;
}
.stats-banner h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}
.stats-banner p { color: var(--text-secondary); }

/* Pagination */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.pagination-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 150ms;
}
.pagination-btn:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.pagination-btn.active { background: var(--accent-blue); color: white; }
.pagination-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* Earnings Calendar */
.earnings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.75rem;
}
.earnings-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 0.875rem;
}
.earnings-date {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-bottom: 0.375rem;
}
.earnings-company { font-weight: 600; font-size: 0.875rem; margin-bottom: 0.5rem; }
.earnings-values { display: flex; gap: 1rem; font-size: 0.75rem; }
.earnings-est { color: var(--text-muted); }
.earnings-act { color: var(--positive); font-weight: 500; }

/* Toggle switch */
.toggle-container {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.toggle {
  width: 36px;
  height: 20px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  position: relative;
  cursor: pointer;
  transition: background 200ms;
}
.toggle.active { background: var(--accent-blue); }
.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms;
}
.toggle.active::after { transform: translateX(16px); }

/* Responsive */
@media (max-width: 1200px) {
  .chart-layout { grid-template-columns: 220px 1fr 280px; }
}
@media (max-width: 1024px) {
  .chart-layout { grid-template-columns: 1fr; }
  .watchlist-sidebar, .chart-panel { display: none; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 1.75rem; }
  .market-summary { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .ideas-grid { grid-template-columns: 1fr; }
  .broker-cards { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .market-summary { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeIn 300ms ease-out; }
